import { useEffect,useState } from "react";
interface Props{design_id:number;revision_id?:number;projectId?:string;preview?:boolean}
export default function PCBDesignCard({design_id,projectId="",preview}:Props){const sample={schema:"apteva-pcb/v1",board:{width_nm:50000000,height_nm:30000000},components:[{id:"u1",designator:"U1",position:{x_nm:26000000,y_nm:15000000,rotation_udeg:0},body:{width_nm:8000000,height_nm:7000000},pads:[{id:"1",x_nm:-4000000,y_nm:-1500000,width_nm:1000000,height_nm:500000,layers:["F.Cu"]},{id:"2",x_nm:-4000000,y_nm:1500000,width_nm:1000000,height_nm:500000,layers:["F.Cu"]}]},{id:"j1",designator:"J1",position:{x_nm:6000000,y_nm:15000000,rotation_udeg:0},body:{width_nm:7000000,height_nm:9000000},pads:[]}],nets:[{},{}],traces:[{id:"dp",layer:"F.Cu",width_nm:250000,points:[{x_nm:9500000,y_nm:13500000},{x_nm:22000000,y_nm:13500000}]},{id:"dm",layer:"F.Cu",width_nm:250000,points:[{x_nm:9500000,y_nm:16500000},{x_nm:22000000,y_nm:16500000}]}],zones:[],keepouts:[]};const [design,setDesign]=useState<any>(preview?{name:"Controller board",status:"validated",current_revision:{number:3,definition:sample},validation:{status:"passed",errors:0,warnings:0}}:null);useEffect(()=>{if(preview||!design_id)return;fetch(`/api/apps/pcb/api/designs/${design_id}?project_id=${encodeURIComponent(projectId)}`,{credentials:"same-origin"}).then(r=>r.json()).then(j=>setDesign(j.design)).catch(()=>setDesign(null))},[design_id,projectId,preview]);if(!design)return <div className="rounded-lg border border-border bg-bg-card p-3 text-xs text-text-muted">PCB design unavailable</div>;const def=design.current_revision?.definition;return <div className="min-w-[300px] overflow-hidden rounded-xl border border-border bg-bg-card shadow-sm"><div className="relative h-32 border-b border-border bg-[#0b0907] p-3">{def?<BoardThumb definition={def}/>:null}<span className="absolute left-2.5 top-2.5 rounded-md border border-accent/25 bg-bg/80 px-2 py-1 text-[8px] font-bold uppercase tracking-wider text-accent backdrop-blur">Apteva PCB</span><span className="absolute right-2.5 top-2.5 rounded-md border border-border bg-bg/80 px-2 py-1 text-[9px] text-text-muted backdrop-blur">native layout</span></div><div className="p-3"><div className="flex items-center gap-2"><span className="grid h-6 w-6 place-items-center rounded-md bg-accent/10 text-accent"><PCBCardMark/></span><strong className="truncate text-sm font-semibold">{design.name}</strong><span className="ml-auto font-mono text-[10px] text-text-muted">r{design.current_revision?.number}</span></div><div className="mt-2.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-[10px] text-text-muted"><span>{def?`${def.board.width_nm/1e6} × ${def.board.height_nm/1e6} mm`:"PCB"}</span><span>·</span><span>{def?.components?.length||0} parts</span><span>·</span><span>{def?.components?.reduce((n:number,c:any)=>n+(c.pads?.length||0),0)||0} pads</span><span className={design.validation?.status==="passed"?"ml-auto text-green":"ml-auto"}>● {design.validation?.status||design.status}</span></div></div></div>}

function BoardThumb({definition:d}:{definition:any}){const mm=(n:number)=>n/1e6,w=mm(d.board.width_nm),h=mm(d.board.height_nm),pts=(a:any[])=>a.map(p=>`${mm(p.x_nm)},${mm(p.y_nm)}`).join(" ");return <svg viewBox={`-2 -2 ${w+4} ${h+4}`} className="h-full w-full drop-shadow-xl"><defs><linearGradient id="card-board"><stop stopColor="#21170f"/><stop offset="1" stopColor="#130e0a"/></linearGradient><pattern id="card-grid" width="2" height="2" patternUnits="userSpaceOnUse"><path d="M2 0H0V2" fill="none" stroke="#d0ccc8" strokeOpacity=".055" strokeWidth=".04"/></pattern></defs><rect width={w} height={h} rx="1.3" fill="url(#card-board)" stroke="var(--color-accent,#f97316)" strokeWidth=".22"/><rect width={w} height={h} rx="1.3" fill="url(#card-grid)"/>{(d.zones||[]).map((z:any)=><polygon key={z.id} points={pts(z.polygon)} fill={z.layer==="B.Cu"?"#b45309":"#f97316"} opacity=".13"/>)}{(d.traces||[]).map((t:any)=><polyline key={t.id} points={pts(t.points)} fill="none" stroke={t.layer==="B.Cu"?"#b45309":"#f97316"} strokeWidth={Math.max(.15,mm(t.width_nm))} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={t.layer==="B.Cu"?".55 .22":undefined}/>)}{(d.components||[]).map((c:any)=>{const b=c.body||{width_nm:3000000,height_nm:2000000};return <g key={c.id} transform={`translate(${mm(c.position.x_nm)} ${mm(c.position.y_nm)}) rotate(${(c.position.rotation_udeg||0)/1e6})`}><rect x={-mm(b.width_nm)/2} y={-mm(b.height_nm)/2} width={mm(b.width_nm)} height={mm(b.height_nm)} rx=".25" fill="#171411" stroke="#d0ccc8" strokeWidth=".1"/>{(c.pads||[]).map((p:any)=><rect key={p.id} x={mm(p.x_nm-p.width_nm/2)} y={mm(p.y_nm-p.height_nm/2)} width={mm(p.width_nm)} height={mm(p.height_nm)} rx=".1" fill={p.layers?.includes("F.Cu")?"#fb923c":"#d97706"}/>) }<text y={-mm(b.height_nm)/2-.35} textAnchor="middle" fontSize=".65" fill="#f5f2ef">{c.designator}</text></g>})}</svg>}
function PCBCardMark(){return <svg viewBox="0 0 24 24" className="h-3.5 w-3.5 fill-none stroke-current" strokeWidth="1.8"><rect x="3.5" y="3.5" width="17" height="17" rx="3"/><circle cx="8" cy="8" r="1.2"/><circle cx="16" cy="16" r="1.2"/><path d="M9.2 8h3.2l2.1 2.1v4.7M8 9.2V16h6.8"/></svg>}
